/** Shape of a terrain, as data. Every preset is generated by the same code in noise.ts. */
export interface Preset {
  id: PresetId;
  label: string;
  /** Most octaves to add; the finest octave is one cell, so small grids add fewer. */
  octaves: number;
  /** Amplitude of the first octave as a fraction of the grid size. */
  amplitude: number;
  /** Amplitude factor from one octave to the next. */
  gain: number;
  /** Fold each octave into sharp ridges. */
  ridged: boolean;
  /** Sideways displacement of the sample point, as a fraction of the grid size. 0 means none. */
  warp: number;
}

export type PresetId = 'alpine' | 'hills' | 'canyon';

export const presets: Record<PresetId, Preset> = {
  alpine: {id: 'alpine', label: 'Young alpine range', octaves: 8, amplitude: 0.25, gain: 0.5, ridged: true, warp: 0},
  hills: {id: 'hills', label: 'Old worn hills', octaves: 8, amplitude: 0.25, gain: 0.5, ridged: false, warp: 0},
  canyon: {id: 'canyon', label: 'Desert canyon', octaves: 6, amplitude: 0.25, gain: 0.5, ridged: true, warp: 0.12},
};

export const presetIds: PresetId[] = ['alpine', 'hills', 'canyon'];
